// Used by scorers like prefix-affinity that track routing history.
type observerFunc func(req *Request, targetInstance string)

// WeightedScoring routes requests using a composable scorer pipeline.
//
// Each scorer evaluates all instances on a [0,1] scale. Scores are combined
// with configurable weights: composite = Σ clamp(s_i) × w_i, then argmax.
//
// Available scorers: prefix-affinity (proportional prefix match ratio),
// queue-depth (min-max normalization of EffectiveLoad),
// kv-utilization (1 - KVUtilization), load-balance (1/(1 + EffectiveLoad)).
// See sim/routing_scorers.go and sim/routing_prefix_scorer.go for implementations.
//
// Stateful scorers (prefix-affinity) register observers that update internal
// state after each routing decision. Observers are called after argmax selection.
//
// Higher scores are preferred. Ties broken by first occurrence in snapshot order.
type WeightedScoring struct {
	scorers   []scorerFunc
	weights   []float64 // normalized to sum to 1.0
	observers []observerFunc
}

// Route implements RoutingPolicy for WeightedScoring.
func (ws *WeightedScoring) Route(req *Request, state *RouterState) RoutingDecision {
	snapshots := state.Snapshots
	if len(snapshots) == 0 {
		panic("WeightedScoring.Route: empty snapshots")
	}

	// EVOLVE-BLOCK-START
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Find min/max effective load and total cluster load
	minLoad := snapshots[0].EffectiveLoad()
	maxLoad := minLoad
	totalLoad := 0
	for _, snap := range snapshots {
		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
		if el > maxLoad {
			maxLoad = el
		}
		totalLoad += el
	}
	loadSpread := maxLoad - minLoad
	avgLoad := float64(totalLoad) / float64(len(snapshots))

	// Stepped load-balance boost based on imbalance
	loadBoost := 0.0
	if loadSpread > 2 {
		loadBoost = 0.3
	}
	if loadSpread > 5 {
		loadBoost = 0.6
	}
	if loadSpread > 10 {
		loadBoost = 0.8
	}

	// Request characteristics
	isRealtime := req.SLOClass == "realtime" || req.SLOClass == "interactive"
	isLargeInput := len(req.InputTokens) > 512
	inputLen := len(req.InputTokens)

	for _, snap := range snapshots {
		el := snap.EffectiveLoad()

		// Smooth quadratic load penalty
		loadPenalty := 1.0 / (1.0 + float64(el)*float64(el)*0.04)
		scores[snap.ID] = scores[snap.ID]*(1.0-loadBoost) + loadPenalty*loadBoost

		// Queue-aware: penalize high queue depth more (waiting vs processing)
		if snap.QueueDepth > 2 {
			qPenalty := 1.0 / (1.0 + float64(snap.QueueDepth-2)*0.2)
			scores[snap.ID] *= (0.6 + 0.4*qPenalty)
		}

		// Cache hit bonus for lightly loaded instances
		if el <= minLoad+2 && snap.CacheHitRate > 0.15 {
			scores[snap.ID] += snap.CacheHitRate * 0.2
		}

		// KV memory pressure: graduated penalty
		if snap.KVUtilization > 0.78 {
			penalty := (snap.KVUtilization - 0.78) * 2.0
			if penalty > 0.55 {
				penalty = 0.55
			}
			if isLargeInput {
				penalty *= 1.3
				if penalty > 0.65 {
					penalty = 0.65
				}
			}
			scores[snap.ID] *= (1.0 - penalty)
		}

		// Realtime/interactive: strongly avoid loaded instances
		if isRealtime && el > minLoad+2 {
			scores[snap.ID] *= 0.35
		}

		// Large inputs penalize loaded instances more
		if isLargeInput && el > minLoad+1 {
			scores[snap.ID] *= 0.55
		}

		// Under high cluster load, strongly prefer instances with free KV blocks
		if snap.FreeKVBlocks > 0 && avgLoad > 3.0 {
			kvBonus := float64(snap.FreeKVBlocks) / (float64(snap.FreeKVBlocks) + 80.0)
			scores[snap.ID] += kvBonus * 0.08
		}

		// Batch-size aware: prefer instances with smaller active batches for faster prefill
		if inputLen > 256 && snap.BatchSize > 3 {
			scores[snap.ID] *= 0.85
		}

		// Floor to avoid zero scores
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		} else if scores[snap.ID] == bestScore && snap.EffectiveLoad() < snapshots[bestIdx].EffectiveLoad() {
			bestIdx = i
		}
	}
	// EVOLVE-BLOCK-END

	// Notify observers of routing decision (stateful scorers update their state)
	for _, obs := range ws.observers {
		obs(req, snapshots[bestIdx].ID)
	}

	return NewRoutingDecisionWithScores(
